#pragma once

#include <memory>
#include <mutex>
#include <string>
#include <vector>

#include <cpprest/json.h>

#include "Error.hpp"

class AnisetteData;

class RemoteAnisetteError : public LocalizedError
{
public:
	virtual std::string domain() const { return "AltServer.RemoteAnisetteError"; }

	using LocalizedError::LocalizedError; // Inherit constructor
};

// Fetches Mac anisette data from an anisette v3 server (https://github.com/SideStore/anisette-v3-server protocol).
// Since 2026-10-22, Apple refuses to issue Xcode auth tokens for anisette data generated by iCloud for Windows (-80046),
// and rejects requests claiming to be a Mac with it (-22410), so we need anisette data generated by an actual Mac.
class RemoteAnisetteProvider
{
public:
	static RemoteAnisetteProvider* instance();

	// Set ALTSERVER_ANISETTE=local to use iCloud for Windows instead.
	static bool isEnabled();

	std::shared_ptr<AnisetteData> FetchAnisetteData();
	void ResetProvisioning();

private:
	RemoteAnisetteProvider();

	static RemoteAnisetteProvider* _instance;

	std::mutex _mutex;
	web::json::value _state;

	std::vector<std::string> serverURLs() const;

	std::shared_ptr<AnisetteData> FetchAnisetteData(const std::string& serverURL);
	std::string Provision(const std::string& serverURL, const std::string& clientInfo, const std::string& userAgent);

	std::vector<unsigned char> identifier();
	std::string deviceID();
	std::string localUserID();

	void LoadState();
	void SaveState();
};
